from scipy.optimize import least_squares
def run(extra, nk):
    def build(p):
        A=[np.exp(-p[0]*x**2), (t**2/(1+p[1]*t**2))*v**3]
        A+= [f(p) for f in extra]
        return np.column_stack(A)
    def resid(p):
        M=build(p)
        c=np.linalg.lstsq(M,y,rcond=None)[0]
        r=y-M@c
        return np.nan_to_num(r,nan=1e3,posinf=1e3,neginf=-1e3)
    best=None; errs=[]
    rng=np.random.default_rng(0)
    for _ in range(25):
        q0=rng.uniform(0.05,2,size=nk)
        try:
            s=least_squares(resid,q0,bounds=(-5,5))
            if best is None or s.cost<best.cost: best=s
        except Exception as e: errs.append(str(e)[:60])
    if best is None: return ('fail',errs[:1])
    M=build(best.x); c=np.linalg.lstsq(M,y,rcond=None)[0]
    return np.mean((y-M@c)**2)/np.var(y), best.x, c
